  references: {
  "_readme": "Reference facts for the Apollo 15 simulator. Split into two groups: FLOWN_HARDWARE (what Apollo 15 actually used in 1971 — cited to the Apollo 15 Mission Report and contemporaneous NASA engineering documents) and MODERN_COMPARISON (today's ISS-era NASA-STD-3001 standards, shown only for contrast — they did not exist in 1971 and never governed this mission). An earlier version of this file applied modern ISS thresholds (cabin CO2/O2/pressure limits, a daily exercise-compliance regimen) directly to Apollo hardware; that was a mismatch and has been corrected here — see README 'Corrections' section.",
  "flown_hardware": {
    "cabin_atmosphere": {
      "value": "100% oxygen, nominal 5.0 psia (34.5 kPa); emergency floor 3.5 psia (24.1 kPa)",
      "note": "Apollo CM and LM both used a pure-oxygen, low-pressure cabin — not the nitrogen/oxygen mix and ~14.7 psia used on the ISS today. Launch-day atmosphere was a mixed sea-level-pressure gas, bled down to 5 psia pure O2 during ascent/early translunar coast (a post-Apollo-1 safety change).",
      "source": "Biomedical Results of Apollo (NASA SP-368), Ch. \"Command and Service Module Environmental Control System\"; NASA feature '50th Anniversary of NASA Deciding on a Mixed-Gas Atmosphere for Apollo'"
    },
    "co2_removal": {
      "value": "Lithium hydroxide (LiOH) canisters, no automated ppCO2 alarm threshold used in this app",
      "note": "Apollo used disposable LiOH canisters, not the ISS's regenerable CDRA system. No continuous cabin-CO2 telemetry for Apollo 15 was located in the sources used to build this prototype, so this app does not chart a CO2 trend for this mission — it states the real removal method as context instead of inventing numbers.",
      "source": "General Apollo ECS documentation (NASA SP-368); this app does not extend beyond what was sourced"
    },
    "biosensors": {
      "value": "ECG (heart rate) and impedance pneumogram (respiration rate) only",
      "note": "No pulse oximetry (SpO2) and no continuous skin-temperature telemetry existed in the 1971 bioharness — both are anachronistic for this mission and were removed from this app's Vitals panel accordingly.",
      "source": "Apollo 15 Mission Report, Section 10.1 (Biomedical Instrumentation and Physiological Data)"
    },
    "food": {
      "value": "~2,800 kcal/day planned; actual average intake 2,801 (CDR) / 2,372 (CMP) / 2,568 (LMP) kcal/day",
      "source": "Apollo 15 Mission Report, Section 10.2.7 (Food)"
    },
    "radiation": {
      "value": "Net integrated dose 360 millirad (CDR), 510 millirad (LMP); passive dosimeter average 300 millirad at skin depth — well below thresholds for detectable medical effect",
      "source": "Apollo 15 Mission Report, Section 10.2.4 (Radiation)"
    },
    "bone_mineral": {
      "value": "Radius: essentially no change. Heel bone (os calcis): the Commander regained mineral faster than the Command Module Pilot, and the Lunar Module Pilot's heel-bone change matched bed-rest results. No percentage loss is stated here because the figure used in an earlier version of this file could not be verified.",
      "note": "Pre/post-flight photon-absorptiometry (experiment M-078), not a continuous in-flight measurement or a model. Apollo 15 lasted 12.3 days and was not instrumented for in-flight bone tracking.",
      "source": "Apollo 15 Mission Report, Section 10.4 (Bone Mineral Measurement)"
    },
    "exercise_countermeasures": {
      "value": "None flown as a daily countermeasure regimen",
      "note": "The ISS's ~2.5h/day, 6-days/week aerobic + resistance exercise protocol is a post-Apollo (Skylab-onward) countermeasure developed once missions got long enough for cardiovascular/musculoskeletal deconditioning to matter. Applying it to a 12-day Apollo mission would be anachronistic, so this app's Activity panel tracks real EVA metabolic workload instead of an exercise-compliance percentage.",
      "source": "General spaceflight-medicine literature (Ploutz-Snyder, NASA JSC ISS exercise Rx); absence for Apollo confirmed by the lack of any such program in the Apollo 15 Mission Report"
    }
  },
  "vitals_general_reference": {
    "heart_rate_bpm": {
      "nominal": [
        50,
        100
      ],
      "note": "General clinical resting range, era-independent. EVA-period elevation above this range is expected exertion, not an alert — see 'eva_context' below."
    },
    "respiration_rate": {
      "nominal": [
        12,
        20
      ],
      "note": "General clinical range, era-independent."
    },
    "source": "General clinical reference ranges, not mission- or era-specific."
  },
  "eva_context_rule": "A heart-rate or respiration reading during a logged EVA window is not flagged, however high, because elevated rate from physical exertion during a moonwalk is expected and healthy — the real 1971 concern was Irwin's EKG RHYTHM (paired beats with pauses), not his rate, which is why this app treats the cardiac arrhythmia as a distinct scripted medical event rather than something a simple rate threshold could have caught. A rate-only monitor would have missed exactly the thing that mattered — see README.",
  "modern_comparison": {
    "_readme": "For contrast only — none of the following governed Apollo 15. Included so the app can show how far astronaut health monitoring has moved on since 1971.",
    "cabin_atmosphere_iss": "NASA-STD-3001 Vol 2 [V2 6003, V2 6006]: ~14.2-14.9 psia total pressure, 145-155 mmHg O2 partial pressure, two-gas (N2/O2) mix.",
    "co2_limit_iss": "NASA-STD-3001 Vol 2 [V2 6004]: average 1-hour ppCO2 <= 3.0 mmHg; OCHMO-TB-004.",
    "exercise_iss": "~2.5 h/day, 6 days/week aerobic + resistance exercise (Ploutz-Snyder, ISS ExRx; Smith SM et al., 2012).",
    "sleep_iss": "Scheduled 8.5 h/night; observed spaceflight average ~5.96-6.09 h (Barger LK et al., Lancet Neurology, 2014) — notably, sleep deprivation was already a real problem in 1971 on Apollo 15, as this mission's own sleep-displacement data shows."
  }
},
